<?php
namespace Core;require_once __DIR__.'/Guard.php';require_once __DIR__.'/CurlSafe.php';ml_guard_shield(__FILE__);class HgdActorFetcher{const BASE='https://hongguoduanju.com';const MAX_ACTORS=20;const REQUEST_DELAY_US=2000000;public static function fetch($a){$a=trim((string)$a);if($a===''||!is_numeric($a)){return[];}$b=self::BASE.'/detail?series_id='.urlencode($a);$c=CurlSafe::request($b,[CURLOPT_HTTPHEADER=>['Accept: text/html,application/xhtml+xml'],CURLOPT_TIMEOUT=>8,CURLOPT_CONNECTTIMEOUT=>4,],8);$d=(is_array($c)&&isset($c['body'])&&is_string($c['body']))?$c['body']:'';if($d===''||(int)($c['code']??0)>=400){return[];}return self::parseActors($d);}private static function parseActors($a){$b=[];$c='/<a\s[^>]*href=["\'](?:https?:\/\/hongguoduanju\.com)?\/character\/(\d+)["\'][^>]*>(.*?)<\/a>/is';if(!preg_match_all($c,$a,$d,PREG_SET_ORDER)){return $b;}foreach($d as $e){$f=isset($e[2])?$e[2]:'';$g=strip_tags($f);$g=html_entity_decode($g,ENT_QUOTES,'UTF-8');$g=preg_replace('/\s+/u',' ',$g);$g=trim($g);if($g===''){continue;}$h=$g;$i='';if(preg_match('/^([\x{4e00}-\x{9fa5}]{2,6})\s*饰\s*(.+)$/u',$g,$j)){$h=trim($j[1]);$i=trim($j[2]);}else{if(preg_match('/^([\x{4e00}-\x{9fa5}]{2,6})\s*[·|,，\-–—]\s*(.+)$/u',$g,$j)){$h=trim($j[1]);$i=trim($j[2]);}}if($h===''||$h==='饰'){continue;}if(preg_match('/\d/',$h)){continue;}if(mb_strlen($h)<2||mb_strlen($h)>8){continue;}$k=false;foreach($b as $l){if($l['name']===$h){$k=true;break;}}if($k){continue;}$b[]=['name'=>$h,'character'=>$i,];if(count($b)>=self::MAX_ACTORS){break;}}return $b;}public static function formatActors($a,$b=false){if(!is_array($a)||empty($a)){return'';}$c=[];foreach($a as $d){$e=isset($d['name'])?trim((string)$d['name']):'';if($e===''){continue;}if($b&&!empty($d['character'])){$c[]=$e.'（'.$d['character'].'）';}else{$c[]=$e;}}return implode('、',$c);}}